#!/usr/bin/env bash
# Compares the cards generated by the card prompt before and after 613d8c7
# ("Harden the card prompt against compound questions and document labels").
#
#   ANTHROPIC_API_KEY=... bench/card-prompt-comparison/run.sh
#
# Settings (environment variables):
#   RUNS=3                    generations per fact and per version
#   MODEL=claude-sonnet-5-5   model of the bridge's catalog
#   LANGUAGE=English
#   MAX_CARDS=3               max_cards_per_fact
#   BEFORE=613d8c7^  AFTER=613d8c7
#   OUT=<this dir>/out        where facts.json, before.json, after.json and report.md land
#   DRY_RUN=1                 stop after writing facts.json: no API call
#   KEEP_WORKTREES=1          keep the temporary worktrees (and their vendor/) for a rerun
#   WORKDIR=<dir>             reuse worktrees kept by an earlier run
set -euo pipefail

HERE=$(cd "$(dirname "$0")" && pwd)
REPO=$(git -C "$HERE" rev-parse --show-toplevel)
RUNS=${RUNS:-3}
MODEL=${MODEL:-claude-sonnet-5-5}
LANGUAGE=${LANGUAGE:-English}
MAX_CARDS=${MAX_CARDS:-3}
BEFORE=${BEFORE:-613d8c7^}
AFTER=${AFTER:-613d8c7}
OUT=${OUT:-$HERE/out}
DRY_RUN=${DRY_RUN:-0}

if [[ "$DRY_RUN" != 1 && -z "${ANTHROPIC_API_KEY:-}" ]]; then
    echo "ANTHROPIC_API_KEY is not set (or run with DRY_RUN=1)." >&2
    exit 1
fi

if [[ -n "${WORKDIR:-}" ]]; then
    REUSE=1
else
    REUSE=0
    WORKDIR=$(mktemp -d "${TMPDIR:-/tmp}/card-prompt-comparison.XXXXXX")
fi

cleanup() {
    if [[ "${KEEP_WORKTREES:-0}" == 1 || "$REUSE" == 1 ]]; then
        echo "Worktrees kept in $WORKDIR (rerun with WORKDIR=$WORKDIR)."
        return
    fi
    git -C "$REPO" worktree remove --force "$WORKDIR/before" 2>/dev/null || true
    git -C "$REPO" worktree remove --force "$WORKDIR/after" 2>/dev/null || true
    rm -rf "$WORKDIR"
}
trap cleanup EXIT

prepare() { # <name> <revision>
    local dir="$WORKDIR/$1"
    if [[ ! -d "$dir" ]]; then
        git -C "$REPO" worktree add --detach "$dir" "$2" >/dev/null
    fi
    if [[ ! -f "$dir/vendor/symfony/ai-anthropic-platform/Factory.php" ]]; then
        echo "Installing dependencies for $1 ($2)..."
        # The worktree is throwaway: requiring the bridge there leaves your composer.json alone.
        (cd "$dir" && composer install --no-interaction --no-progress --quiet \
            && composer require --dev --no-interaction --no-progress --quiet 'symfony/ai-anthropic-platform:^1.0@beta')
    fi
}

prepare before "$BEFORE"
prepare after "$AFTER"

mkdir -p "$OUT"
echo "Before: $(git -C "$WORKDIR/before" log -1 --format='%h %s')"
echo "After:  $(git -C "$WORKDIR/after" log -1 --format='%h %s')"

# Facts are extracted once, from the "after" checkout, so both prompts see exactly the same material.
cp "$HERE"/adr/*.md "$WORKDIR/after/tests/Fixtures/docs/adr/"
php "$HERE/extract-facts.php" "$WORKDIR/after" "$OUT/facts.json"

if [[ "$DRY_RUN" == 1 ]]; then
    echo "Dry run: facts written to $OUT/facts.json, no API call made."
    exit 0
fi

for version in before after; do
    php "$HERE/generate.php" "$WORKDIR/$version" "$OUT/facts.json" "$OUT/$version.json" \
        "$version" "$MODEL" "$RUNS" "$MAX_CARDS" "$LANGUAGE"
done

php "$HERE/report.php" "$OUT"
echo "Report: $OUT/report.md"
